<?php
require_once 'includes/config.php';require_admin();
$msg = null;
$error = null;$msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'';try{
  if($action==='class'){$t=(int)$_POST['teacher_id'];$c=(int)$_POST['class_id'];$q=$dbh->prepare('INSERT IGNORE INTO teacher_class_assignments(teacher_id,class_id) VALUES(:t,:c)');$q->execute([':t'=>$t,':c'=>$c]);$msg='Class assigned to teacher.';audit_log($dbh,'TEACHER_CLASS_ASSIGN','Teacher '.$t.' class '.$c);}
  elseif($action==='student'){$t=(int)$_POST['teacher_id'];$c=(int)$_POST['class_id'];$s=(int)$_POST['student_id'];if(!teacher_has_class($dbh,$t,$c))throw new RuntimeException('Assign the teacher to the class before assigning students.');$chk=$dbh->prepare('SELECT 1 FROM tblstudents WHERE StudentId=:s AND ClassId=:c AND Status=1');$chk->execute([':s'=>$s,':c'=>$c]);if(!$chk->fetchColumn())throw new RuntimeException('Student does not belong to the selected class.');$q=$dbh->prepare('INSERT IGNORE INTO teacher_student_assignments(teacher_id,student_id,class_id) VALUES(:t,:s,:c)');$q->execute([':t'=>$t,':s'=>$s,':c'=>$c]);$msg='Student assigned to teacher.';audit_log($dbh,'TEACHER_STUDENT_ASSIGN','Teacher '.$t.' student '.$s);}
  elseif($action==='remove_class'){$q=$dbh->prepare('DELETE FROM teacher_class_assignments WHERE teacher_id=:t AND class_id=:c');$q->execute([':t'=>(int)$_POST['teacher_id'],':c'=>(int)$_POST['class_id']]);$msg='Class assignment removed.';}
  elseif($action==='remove_student'){$q=$dbh->prepare('DELETE FROM teacher_student_assignments WHERE id=:id');$q->execute([':id'=>(int)$_POST['assignment_id']]);$msg='Student assignment removed.';}
 }catch(Throwable $x){$error=$x->getMessage();}
}
$teachers=$dbh->query('SELECT id,username,full_name FROM teachers WHERE status=1 ORDER BY full_name')->fetchAll();$classes=$dbh->query('SELECT id,ClassName,Section FROM tblclasses ORDER BY ClassNameNumeric,Section')->fetchAll();$students=$dbh->query('SELECT StudentId,StudentName,RollId,ClassId FROM tblstudents WHERE Status=1 ORDER BY StudentName')->fetchAll();$ca=$dbh->query('SELECT a.id,t.id teacher_id,t.full_name,c.id class_id,c.ClassName,c.Section FROM teacher_class_assignments a JOIN teachers t ON t.id=a.teacher_id JOIN tblclasses c ON c.id=a.class_id ORDER BY t.full_name,c.ClassNameNumeric,c.Section')->fetchAll();$sa=$dbh->query('SELECT a.id,t.full_name,s.StudentName,s.RollId,c.ClassName,c.Section FROM teacher_student_assignments a JOIN teachers t ON t.id=a.teacher_id JOIN tblstudents s ON s.StudentId=a.student_id JOIN tblclasses c ON c.id=a.class_id ORDER BY t.full_name,c.ClassNameNumeric,s.StudentName')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Teacher Assignments | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><main class="main-page"><div class="container-fluid srms-page"><div class="srms-toolbar"><a href="manage-teachers.php" class="btn btn-default">← Teachers</a></div><h2>Teacher Assignments</h2><?php if($msg):?><div class="alert alert-success"><?php echo e($msg);?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?php echo e($error);?></div><?php endif;?><div class="row"><div class="col-md-6"><div class="panel"><div class="panel-heading"><h4>Assign Teacher to Class</h4></div><div class="panel-body"><form method="post"><?php echo csrf_field();?><input type="hidden" name="action" value="class"><div class="form-group"><label>Teacher</label><select class="form-control" name="teacher_id" required><option value="">Select</option><?php foreach($teachers as $t):?><option value="<?php echo $t['id'];?>"><?php echo e($t['full_name'].' ('.$t['username'].')');?></option><?php endforeach;?></select></div><div class="form-group"><label>Class</label><select class="form-control" name="class_id" required><option value="">Select</option><?php foreach($classes as $c):?><option value="<?php echo $c['id'];?>"><?php echo e($c['ClassName'].' '.$c['Section']);?></option><?php endforeach;?></select></div><button class="btn btn-primary">Assign Class</button></form></div></div></div><div class="col-md-6"><div class="panel"><div class="panel-heading"><h4>Assign Student to Teacher</h4></div><div class="panel-body"><form method="post"><?php echo csrf_field();?><input type="hidden" name="action" value="student"><div class="form-group"><label>Teacher</label><select class="form-control" name="teacher_id" required><?php foreach($teachers as $t):?><option value="<?php echo $t['id'];?>"><?php echo e($t['full_name']);?></option><?php endforeach;?></select></div><div class="form-group"><label>Class</label><select class="form-control" name="class_id" required><?php foreach($classes as $c):?><option value="<?php echo $c['id'];?>"><?php echo e($c['ClassName'].' '.$c['Section']);?></option><?php endforeach;?></select></div><div class="form-group"><label>Student</label><select class="form-control" name="student_id" required><option value="">Select</option><?php foreach($students as $s):?><option value="<?php echo $s['StudentId'];?>"><?php echo e($s['StudentName'].' ('.$s['RollId'].') - Class '.$s['ClassId']);?></option><?php endforeach;?></select></div><button class="btn btn-success">Assign Student</button></form></div></div></div></div><div class="panel"><div class="panel-heading"><h4>Class Assignments</h4></div><div class="panel-body table-responsive"><table class="table table-bordered"><tr><th>Teacher</th><th>Class</th><th>Action</th></tr><?php foreach($ca as $r):?><tr><td><?php echo e($r['full_name']);?></td><td><?php echo e($r['ClassName'].' '.$r['Section']);?></td><td><form method="post"><?php echo csrf_field();?><input type="hidden" name="action" value="remove_class"><input type="hidden" name="teacher_id" value="<?php echo $r['teacher_id'];?>"><input type="hidden" name="class_id" value="<?php echo $r['class_id'];?>"><button class="btn btn-danger btn-xs">Remove</button></form></td></tr><?php endforeach;?></table></div></div><div class="panel"><div class="panel-heading"><h4>Student Assignments</h4></div><div class="panel-body table-responsive"><table class="table table-bordered"><tr><th>Teacher</th><th>Student</th><th>Class</th><th>Action</th></tr><?php foreach($sa as $r):?><tr><td><?php echo e($r['full_name']);?></td><td><?php echo e($r['StudentName'].' ('.$r['RollId'].')');?></td><td><?php echo e($r['ClassName'].' '.$r['Section']);?></td><td><form method="post"><?php echo csrf_field();?><input type="hidden" name="action" value="remove_student"><input type="hidden" name="assignment_id" value="<?php echo $r['id'];?>"><button class="btn btn-danger btn-xs">Remove</button></form></td></tr><?php endforeach;?></table></div></div></div></main></div></div></div></div></body></html>
